from pathlib import Path
p=Path('content/research/notes/open-engineering-specification-article-draft.md')
t=p.read_text()
t=t.replace('In Linear Software, relevant consequential behavior is specified before runtime through explicit code, rules, or state transitions.', 'In Linear Software, the intended mapping for relevant consequential behavior is specified before runtime through explicit code, rules, or state transitions.', 1)
